    h = obs.get('hitch_deg', 0.0) or 0.0
    t = obs.get('t', 0.0) or 0.0
    dt = obs.get('dt', 0.1) or 0.1
    mo = obs.get('motion') or {}
    hold = mo.get('hold_s', 0.0) or 0.0
    v = mo.get('v_mps', 0.0) or 0.0
    if _b['ph'] == 'wait':
        if hold > 0:
            return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': 180}
        _b['ph'] = 'fwd'
        _b['t0'] = t
    if _b['ph'] == 'fwd':
        if t - _b['t0'] < 3.0:
            return {'steer_deg': 0.0, 'speed_mps': 0.4, 'look_deg': 0}
        _b['ph'] = 'stop'
        _b['t0'] = t
    if _b['ph'] == 'stop':
        if abs(v) > 0.05 or hold > 0 or t - _b['t0'] < 0.8:
            return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': 180}
        _b['ph'] = 'rev'
        _b['last'] = None
    d = 0.0 if _b['last'] is None else (h - _b['last']) / dt
    _b['last'] = h
    s = max(-30.0, min(30.0, 2.0 * h + 0.3 * d))
    return {'steer_deg': s, 'speed_mps': -0.3, 'look_deg': 180}

